test('searchTodos filters todos by term and options.done', () => {
  const results = searchTodos('groceries', { done: false });
  assert.ok(Array.isArray(results));
  assert.ok(results.every(t => !t.done));
});

test('rankResults sorts todos by matching term frequency', () => {
  const items = [{ title: 'milk' }, { title: 'buy milk chocolate' }];
  const ranked = rankResults('buy milk', items);
  assert.equal(ranked[0].title, 'buy milk chocolate');
});

test('highlight escapes HTML entities and marks matched terms', () => {
  const result = highlight('<script>alert(1)</script> buy milk', 'milk');
  assert.ok(!result.includes('<script>'));
  assert.ok(result.includes('<mark>milk</mark>'));
});

test('searchAndRank returns ranked search matches', () => {
  const res = searchAndRank('test');
  assert.ok(Array.isArray(res));
});

